// AdminDashboard.jsx
// Use case: viewStatistics, trackPlacements
import { useState } from "react";
import AdminLayout from "./AdminLayout";

const STATS = [
  { label:"Total students",    value:"312", icon:"🎓", color:"bg-soft border-soft",   sub:"registered on platform" },
  { label:"Students placed",   value:"187", icon:"✅", color:"bg-blush border-blush",  sub:"internship accepted" },
  { label:"Unplaced students", value:"125", icon:"⏳", color:"bg-cream border-cream",  sub:"still searching" },
  { label:"Companies",         value:"48",  icon:"🏢", color:"bg-rose border-rose",    sub:"active on platform" },
  { label:"Pending validation",value:"9",   icon:"📋", color:"bg-cream border-cream",  sub:"awaiting admin review" },
  { label:"Agreements issued", value:"174", icon:"📄", color:"bg-soft border-soft",    sub:"Convention de Stage" },
];

const RECENT_VALIDATIONS = [
  { student:"Amira Benali",  company:"Sonatrach Digital", role:"Full-Stack Developer", date:"Apr 24", status:"pending"  },
  { student:"Sara Maamri",   company:"Ooredoo Labs",       role:"Data Analyst",         date:"Apr 23", status:"pending"  },
  { student:"Lina Zouaoui",  company:"Djezzy Tech",        role:"Backend Engineer",     date:"Apr 22", status:"validated"},
  { student:"Karim Hadj",    company:"Mobilis IT",         role:"Mobile Developer",     date:"Apr 21", status:"validated"},
];

const PLACEMENT_DATA = [
  { dept:"Informatique",      placed:68, total:90  },
  { dept:"Génie Logiciel",    placed:45, total:60  },
  { dept:"Réseaux & Télécoms",placed:32, total:50  },
  { dept:"Systèmes Embarqués",placed:18, total:35  },
  { dept:"Intelligence Art.", placed:24, total:40  },
];

export default function AdminDashboard() {
  const [active, setActive] = useState("dashboard");
  const pending = RECENT_VALIDATIONS.filter(v => v.status === "pending").length;

  return (
    <AdminLayout active={active} onNav={setActive} pendingCount={pending}>
      <div className="p-5 md:p-8 max-w-6xl mx-auto">

        {/* Header */}
        <div className="anim-fade-up mb-7">
          <p className="text-xs font-semibold text-[#2E7DF7] uppercase tracking-widest mb-1">Overview</p>
          <h1 className="font-syne font-extrabold text-slate-900 text-2xl md:text-3xl tracking-tight">Admin dashboard</h1>
          <p className="text-slate-400 text-sm font-light mt-0.5">IFA — Internship Office · 2025–2026 · 2nd Semester</p>
        </div>

        {/* Stats grid */}
        <div className="anim-fade-up anim-d1 grid grid-cols-2 md:grid-cols-3 gap-3 mb-7">
          {STATS.map(({ label, value, icon, color, sub }) => (
            <div key={label} className={`card border p-4 ${color}`}>
              <div className="text-xl mb-2">{icon}</div>
              <div className="font-syne font-extrabold text-2xl text-slate-900">{value}</div>
              <div className="text-xs font-semibold text-slate-700 mt-0.5">{label}</div>
              <div className="text-xs text-slate-400 mt-0.5">{sub}</div>
            </div>
          ))}
        </div>

        <div className="grid md:grid-cols-5 gap-5">

          {/* Placement by department */}
          <div className="md:col-span-3 anim-fade-up anim-d2">
            <div className="flex items-center justify-between mb-3">
              <h2 className="font-syne font-bold text-slate-800 text-base">Placement by department</h2>
              <button onClick={() => setActive("students")} className="text-xs text-[#2E7DF7] font-medium hover:underline">View all →</button>
            </div>
            <div className="card border border-slate-200 p-5 space-y-4">
              {PLACEMENT_DATA.map(({ dept, placed, total }) => {
                const pct = Math.round((placed / total) * 100);
                return (
                  <div key={dept}>

                  
                  <div className="flex justify-between items-center mb-1.5">
                      <span className="text-sm font-medium text-slate-700">{dept}</span>
                      <span className="text-xs text-slate-500">{placed}/{total} <span className="font-semibold text-slate-700">({pct}%)</span></span>
                    </div>
                    <div className="h-2 bg-slate-100 rounded-full overflow-hidden">
                      <div className="progress-bar-inner" style={{ width:` ${pct} %`}} />
                    </div>
                  </div>
                );
              })}

              {/* Overall */}
              <div className="pt-3 border-t border-slate-100">
                <div className="flex justify-between items-center mb-1.5">
                  <span className="text-sm font-bold text-slate-800">Overall placement rate</span>
                  <span className="text-sm font-bold text-[#2E7DF7]">60%</span>
                </div>
                <div className="h-2.5 bg-slate-100 rounded-full overflow-hidden">
                  <div className="progress-bar-inner" style={{ width: "60%" }} />
                </div>
              </div>
            </div>
          </div>

          {/* Recent validations */}
          <div className="md:col-span-2 anim-fade-up anim-d3">
            <div className="flex items-center justify-between mb-3">
              <h2 className="font-syne font-bold text-slate-800 text-base">Recent validations</h2>
              <button onClick={() => setActive("validations")} className="text-xs text-[#2E7DF7] font-medium hover:underline">All →</button>
            </div>
            <div className="card border border-slate-200 divide-y divide-slate-100">
              {RECENT_VALIDATIONS.map((v, i) => (
                <div key={i} className="p-3.5">
                  <div className="flex items-start justify-between gap-2 mb-1">
                    <div>
                      <div className="text-sm font-semibold text-slate-800">{v.student}</div>
                      <div className="text-xs text-slate-400">{v.company}</div>
                    </div>
                    <span className={`badge shrink-0 ${v.status === "pending" ? "badge-orange" : "badge-green"}`}>
                      {v.status === "pending" ? "Pending" : "Validated"}
                    </span>
                  </div>
                  <div className="text-xs text-slate-400">{v.role} · {v.date}</div>
                </div>
              ))}
            </div>

            {/* Quick action */}
            <div className="mt-3 card border border-soft bg-soft/40 p-4">
              <p className="text-xs font-semibold text-slate-700 mb-1">⚡ {pending} agreements waiting</p>
              <p className="text-xs text-slate-500 mb-2">Review and validate internship agreements to unblock students.</p>
              <button onClick={() => setActive("validations")}
                className="shimmer-btn text-white text-xs font-semibold px-4 py-2 rounded-lg w-full">
                Go to validations →
              </button>
            </div>
          </div>

        </div>
      </div>
    </AdminLayout>
  );
}
